```cpp[]
class Solution {
  public:
    int maxLen(vector<int>& nums) {
        // Your code goes here
        int n = nums.size();
        if(n == 0){
            return 0;
        }
        int maxLen = 0;
        vector<int> preSum(n);
        preSum[0] = nums[0];
        for(int i = 1; i < n; i++){
            preSum[i] = preSum[i-1] + nums[i];
        }
        unordered_map<int, int> mp;
        for(int i = 0; i < n; i++){
            if(preSum[i] == 0){
                int len = i+1;
                maxLen = max(maxLen, len);
            }
            if(mp.find(preSum[i]) == mp.end()){
                mp[preSum[i]] = i;
            }
            else{
                int len = i - mp[preSum[i]];
                maxLen = max(maxLen, len);
            }
        }

        if(maxLen <= 0){
            return 0;
        }
        return maxLen;
    }
};
```

